SELECT "TableroSistemaPenal_6"."AUDIENCIA" AS "AUDIENCIA",   SUM(CAST("TableroSistemaPenal_6"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok",   CAST(EXTRACT(YEAR FROM "TableroSistemaPenal_6"."FECHA_AUDIENCIA") AS BIGINT) AS "yr_FECHA_AUDIENCIA_ok" FROM "TableroSistemaPenal_6" WHERE ("TableroSistemaPenal_6"."TIP_TRIB" = 'Garantía') AND EXISTS ( SELECT 1 AS "one" FROM (   SELECT "TableroSistemaPenal_6"."AUDIENCIA" AS "AUDIENCIA",     SUM(1) AS "___alias__0"   FROM "TableroSistemaPenal_6"   WHERE (("TableroSistemaPenal_6"."AUDIENCIA" >= 'AUDIENCIA ART. 186') AND ("TableroSistemaPenal_6"."AUDIENCIA" <= 'AUDIENCIA PRESENTACIÓN VOL.IMPUTADO C/ORD. DETEN.'))   GROUP BY "TableroSistemaPenal_6"."AUDIENCIA"   ORDER BY "___alias__0" DESC   LIMIT 10 ) "t0" WHERE ("TableroSistemaPenal_6"."AUDIENCIA" = "t0"."AUDIENCIA") ) GROUP BY "TableroSistemaPenal_6"."AUDIENCIA",   "yr_FECHA_AUDIENCIA_ok";
